<?php
/*
 * Feed output for Full-Text RSS.
 *
 * RSS 2.0 is generated by the upstream "mibe/FeedWriter" library (GPL-3.0-or-later),
 * pinned to tag v1.1.2, commit b32ed2a68e612a1f6045d00d342df6928ecfecad.
 * Its files are in upstream/ with the licence text (COPYING). See docs/LIBRARIES.md.
 *
 * JSON and JSONP output is not provided upstream and is generated here.
 *
 * This class keeps the call API that makefulltextfeed.php already uses.
 * Modified for Full-Text RSS.
 */

require_once __DIR__ . '/upstream/InvalidOperationException.php';
require_once __DIR__ . '/upstream/Feed.php';
require_once __DIR__ . '/upstream/Item.php';
require_once __DIR__ . '/upstream/RSS2.php';
require_once __DIR__ . '/FeedItem.php';

define('RSS2', 1);
define('JSON', 2);
define('JSONP', 3);

class FeedWriter
{
    private $format;
    private $simpleJson = false;
    private $items = array();
    private $title = 'RSS2 Feed';
    private $description = null;
    private $link = null;
    private $ttl = null;
    private $image = null;
    private $xsl = null;
    private $self = null;
    private $alternate = null;
    private $related = null;
    private $hubs = array();

    public function __construct($format = RSS2)
    {
        $this->format = $format;
    }

    public function setFormat($format)
    {
        $this->format = $format;
    }

    public function enableSimpleJson($enable = true)
    {
        $this->simpleJson = $enable;
    }

    public function setTitle($title)
    {
        $this->title = (string)$title;
    }

    public function setDescription($description)
    {
        $this->description = (string)$description;
    }

    public function setLink($link)
    {
        $this->link = (string)$link;
    }

    public function setTtl($ttl)
    {
        $this->ttl = (int)$ttl;
    }

    public function setImage($title, $link, $url)
    {
        $this->image = array('title' => (string)$title, 'link' => (string)$link, 'url' => (string)$url);
    }

    public function setXsl($xsl)
    {
        $this->xsl = $xsl;
    }

    public function setSelf($url)
    {
        $this->self = $url;
    }

    public function setAlternate($url, $title)
    {
        $this->alternate = array('url' => $url, 'title' => $title);
    }

    public function setRelated($url, $title)
    {
        $this->related = array('url' => $url, 'title' => $title);
    }

    public function addHub($hub)
    {
        $this->hubs[] = $hub;
    }

    public function createNewItem()
    {
        return new FeedItem();
    }

    public function addItem($item)
    {
        $this->items[] = $item;
    }

    /**
     * Sends the headers and the feed body.
     */
    public function generateFeed()
    {
        if ($this->format === JSON || $this->format === JSONP) {
            header('Content-type: ' . ($this->format === JSON ? 'application/json' : 'application/javascript') . '; charset=UTF-8');
            $doc = $this->jsonDocument();
            echo json_encode($this->simpleJson ? $this->simpleDocument($doc) : $doc);
            return;
        }
        header('Content-type: text/xml; charset=UTF-8');
        // line prevents Chrome 20 prompting download
        // used by Google: https://news.google.com/news/feeds?ned=us&topic=b&output=rss
        header('X-content-type-options: nosniff');
        echo $this->rssDocument();
    }

    /**
     * RSS 2.0 document built with the pinned upstream library.
     */
    public function rssDocument()
    {
        $link = ($this->link !== null && $this->link !== '') ? $this->link : ($this->alternate['url'] ?? 'http://localhost/');
        $feed = new FeedWriter\RSS2();
        $feed->addNamespace('media', 'http://search.yahoo.com/mrss/');
        $feed->removeCDATAEncoding(array('description', 'content:encoded', 'summary'));
        $feed->setTitle($this->title !== '' ? $this->title : 'RSS2 Feed');
        $feed->setLink($link);
        $feed->setDescription($this->description !== null && $this->description !== '' ? $this->description : $this->title);
        if ($this->ttl !== null) {
            $feed->setChannelElement('ttl', (string)$this->ttl);
        }
        if ($this->image !== null && $this->image['url'] !== '' && $this->image['title'] !== '' && $this->image['link'] !== '') {
            $feed->setImage($this->image['url'], $this->image['title'], $this->image['link']);
        }
        if ($this->self !== null && $this->self !== '') {
            $feed->setSelfLink($this->self);
        }
        if ($this->alternate !== null && $this->alternate['url'] !== '') {
            $feed->setAtomLink($this->alternate['url'], 'alternate', null, null, $this->alternate['title'] ?: null);
        }
        if ($this->related !== null && $this->related['url'] !== '') {
            $feed->setAtomLink($this->related['url'], 'related', null, null, $this->related['title'] ?: null);
        }
        foreach ($this->hubs as $hub) {
            $feed->setAtomLink($hub, 'hub');
        }
        foreach ($this->items as $item) {
            $feed->addItem($item->buildRss($feed));
        }
        $xml = $feed->generateFeed();
        if ($this->xsl) {
            $xml = preg_replace('/^(<\?xml[^>]*\?>\R)/', '$1<?xml-stylesheet type="text/xsl" href="' . htmlspecialchars($this->xsl, ENT_QUOTES, 'UTF-8') . '"?>' . PHP_EOL, $xml, 1);
        }
        return $xml;
    }

    /**
     * JSON document in the shape of the previous FiveFilters output:
     * { "rss": { "@attributes": {"version": "2.0"}, "channel": {...} } }
     */
    public function jsonDocument()
    {
        $link = ($this->link !== null && $this->link !== '') ? $this->link : ($this->alternate['url'] ?? 'http://localhost/');
        $channel = array(
            'title' => $this->title,
            'link' => $link,
            'description' => $this->description !== null && $this->description !== '' ? $this->description : $this->title,
        );
        if ($this->ttl !== null) {
            $channel['ttl'] = $this->ttl;
        }
        if ($this->image !== null) {
            $channel['image'] = $this->image;
        }
        $items = array();
        foreach ($this->items as $item) {
            $items[] = $item->buildJson();
        }
        if (count($items) === 1) {
            $channel['item'] = $items[0];
        } elseif (count($items) > 1) {
            $channel['item'] = $items;
        }
        return array('rss' => array('@attributes' => array('version' => '2.0'), 'channel' => (object)$channel));
    }

    /**
     * Reduced JSON used by the "simple" mode: fields of the first item only.
     */
    private function simpleDocument($doc)
    {
        $item = $doc['rss']['channel']->item ?? null;
        if (is_array($item)) {
            $item = $item[0] ?? null;
        }
        $get = function ($k) use ($item) {
            return ($item && isset($item->$k)) ? $item->$k : null;
        };
        $simple = new stdClass();
        $simple->title = $get('title');
        $simple->excerpt = null;
        $simple->date = null;
        $simple->author = $get('dc_creator');
        $simple->language = $get('dc_language');
        $simple->url = $get('link');
        $simple->effective_url = $get('dc_identifier');
        $simple->domain = strtolower((string)@parse_url((string)$simple->effective_url, PHP_URL_HOST));
        if (substr($simple->domain, 0, 4) === 'www.') {
            $simple->domain = substr($simple->domain, 4);
        }
        $simple->word_count = null;
        $simple->og_url = $get('og_url');
        $simple->og_title = $get('og_title');
        $simple->og_description = $get('og_description');
        $simple->og_image = $get('og_image');
        $simple->og_type = $get('og_type');
        $simple->twitter_card = $get('twitter_card');
        $simple->twitter_site = $get('twitter_site');
        $simple->twitter_creator = $get('twitter_creator');
        $simple->twitter_image = $get('twitter_image');
        $simple->twitter_title = $get('twitter_title');
        $simple->twitter_description = $get('twitter_description');
        if ($get('content_encoded') !== null) {
            $simple->content = $get('content_encoded');
            $simple->word_count = count(preg_split('!\s+!', strip_tags($simple->content), -1, PREG_SPLIT_NO_EMPTY));
            $simple->excerpt = $get('description');
        } else {
            $simple->content = $get('description');
        }
        if ($get('pubDate') !== null) {
            $simple->date = gmdate(DATE_ATOM, strtotime($get('pubDate')));
        }
        return $simple;
    }
}
